// ValoriSensore: ritorna i valori dei sensori ordinati
function ValoriSensore(stationdata) {
    let sensors = {};

    stationdata.data.forEach((item) => {
        if (!sensors[item.tipo]) {
            sensors[item.tipo] = {
                data: [],
                label: item.nome_sensore,
                unitmeas: item.unitnm,
                dMinima: new Date(),
                dMassima: new Date(),
                passo: 60*60*1000           // 1 ora in in millisecondi 
            }
        }

        // nome della stazione dei dati visualizzati
        nomeStazione = item.nome_stazione;
        // momento di aggiornamento dei dati visualizzati
        aggiornamento = item.aggiornamento;

        // se il valore contiene una , (separatore delle migliaia) la tolgo
        let valore = item.valore.replace(',','');
        // se radiazione solare con unità di misura MJ/m2 la converto in W/m2
        if (sensors[item.tipo].unitmeas == 'MJ/m2') {
           valore = Math.round( valore * 277.7 );   // da MJ/m2 a W/m2 
        }

        // se visibilità allora metto in km
        if (item.tipo == 'VISIB') {
            valore = valore / 1000;    // da metri a km

            // arrotondamenti in base al numero
            if (valore > 10) { 
                valore = Math.round(valore); 
            } else {
                // 3 decimali
                valore = Math.round(valore*Math.pow(10,3))/Math.pow(10,3); 
            }

        }

        sensors[item.tipo].data.push({
            value: valore,
            date: item.dataora,
            timestamp: new Date().ConvIstante( item.dataora )
        });
    });

    // se unitmeas == "MJ/m2" correggo l'unità di misura in quanto ne ho appena modificato tutti i valori
    // se unitmeas == "magarcsec2" la metto più leggibile mag/arcsec2
    Object.entries(sensors).forEach(entry => {
      const [key, sensore] = entry;
      if (sensore.unitmeas == "MJ/m2") {
          sensors[key].unitmeas = "W/m2";
      }
      if (key == 'VISIB') {
          sensors[key].unitmeas = "km";
      }

    });

    // se ho la pioggia aggiungo il sensore PRECCUM con la cumulata giornaliera
    Object.entries(sensors).forEach(entry => {
        const [type, sensore] = entry;
        if (type == 'PREC') {
            // nuovo sensore della precipitazione cumulata giornaliera
            const sPrecCum = 'PRECCUM'; 
            sensors[ sPrecCum ] = {
                data: [],
                label: 'Precipitazione cumulata',
                unitmeas: sensore.unitmeas,
                dMinima: new Date(),
                dMassima: new Date(),
                passo: 60*60*1000           // 1 ora in in millisecondi 
            }
            // per tutti i dati di pioggia ne calcolo la cumulata giornaliera nel sensore PRECCUM
            let pCum = 0;
            let oldDay = '';
            sensore.data.forEach((tuplaDatiSensore, index) => {
                var dataora = tuplaDatiSensore.date;      // var dataora = FormatTime('DD/MM/YYYY HH:mm', xvalori.value[0]);
                var valore = tuplaDatiSensore.value;

                // primo ingresso
                if (oldDay == '') { 
                    oldDay = dataora.substring(0, 10);
                }

                myConsoleLog('PRECCUM dataora ' + dataora + ' valore ' + valore + ' cumulata prima ' + pCum + ' dopo ' + (pCum + Math.round( valore * 10) / 10) );

                if ( isNumeric( valore ) ) { 
                    pCum += Math.round( valore * 10) / 10;
                }  

                sensors[ sPrecCum ].data.push({
                    value: parseFloat(pCum).toFixed(1),
                    date: dataora,
                    timestamp: new Date().ConvIstante( dataora )
                });

                // al cambio di giorno la cumulata si azzera
                if ( oldDay != dataora.substring(0, 10) ) {
                    oldDay = dataora.substring(0, 10);
                    pCum = 0;
                }


            });
        }
    });

    // se ho il sensore di BRILLANZA ci aggiungo le scansioni a 5 minuti mancanti
    if (sensors['BRILLAIST']) {

        // scorro la brillanza e carico le scansioni orarie mancanti
        // 2022-09-12T01:00:00
        // 2022-09-12T00:00:00.000Z
        var brill = sensors[ 'BRILLAIST' ];

        myConsoleLog( 'BRILLAIST prima ' + JSON.stringify( sensors[ 'BRILLAIST' ] ) );        

        var valori = [];
        var dAttesa = new Date().ConvIstante( brill.data[0].date )
        brill.data.forEach((valore, index) => {
            let datacorr = new Date().ConvIstante( brill.data[index].date );
            myConsoleLog('dAttesa=' + dAttesa.Formato('YYYY-MM-DDTHH-mm') + ' datacorr=' + datacorr.Formato('YYYY-MM-DDTHH-mm') );                

            // finchè la dPrec è inferiore alla data corrente aggiungo valori a 0
            while (dAttesa.getTime() < datacorr.getTime() ) {
                myConsoleLog('aggiunto 0 alla dAttesa=' + dAttesa.Formato('YYYY-MM-DDTHH-mm') );                

                valori.push( { date : dAttesa.Formato('YYYY-MM-DDTHH-mm'), value: 0, timestamp: dAttesa } );
                dAttesa.addMinutes(5);

            }
            valori.push( {date : brill.data[index].date, value: brill.data[index].value, timestamp: brill.data[index].timestamp });
            dAttesa.addMinutes(5);

        });
        // cambio l'array dei valori
        sensors[ 'BRILLAIST' ].data = valori;     

        myConsoleLog( 'BRILLAIST dopo ' + JSON.stringify( sensors[ 'BRILLAIST' ] ) );        

    }

    // da tutti i sensori cerco i limiti temporali di riferimento
    // cerco la data iniziale, la finale ed il passo temporale del sensore
    var dMinima  = new Date();
    var dMassima = new Date();
    var bPrimo = true;
    Object.entries(sensors).forEach(entry => {
        const [type, sensor] = entry;

        var dPrecedente = new Date(), dPasso = (60*60*1000);   // 1 ora in in millisecondi 
        var bPrimoLocal = true;
        sensor.data.forEach((valore, index) => {
            if (bPrimo) {
                bPrimo = false;
                dMinima = valore.timestamp;
                dMassima = valore.timestamp;
            }
            if (bPrimoLocal) {
                bPrimoLocal = false;
                dPrecedente = valore.timestamp;
            }

            dMinima = new Date( Math.min(dMinima, valore.timestamp) );
            dMassima = new Date( Math.max(dMassima, valore.timestamp) );
            // cerco il passo minore
            if (dPrecedente != valore.timestamp) {
                dPasso = Math.min(dPrecedente, (valore.timestamp - dPrecedente) );
            }
            dPrecedente = valore.timestamp;
        });

        sensors[type].passo = dPasso;

    });
    // valorizzo le date minima e massima per graficarle bene
    Object.entries(sensors).forEach(entry => {
        const [type, sensor] = entry;
        sensors[type].dMinima = dMinima;
        sensors[type].dMassima = dMassima;
    });

    return sensors;    
}


