/*------------------------------------------------------------------------------
  Ritorna la temperatura di rugiada
*/
function TRugiada(temp, umid) {
    temp = 1 * temp;
    umid = 1 * umid;
    var enat = 2.71828182845905, atdew = 17.27, btdew = 237.7, alfa, ru;
    alfa = atdew * temp / (btdew + temp) + Math.log(umid / 100) / Math.log(enat);
    ru = btdew * alfa / (atdew - alfa);
    ru = parseFloat(Math.round(ru * 10) / 10).toFixed(1);
    return ru;
}    

