// grafico specifico per la precipitazione ( ci metto nel secondo asse la cumulata giornaliera )
function GraficoPREC(type, sensors) {
    myConsoleLog('GraficoPREC');

    // creo il grafico standard a barre a cui aggiungo la precipitazione cumulata nel secondo asse
    var myChart = GraficoStandard(type, sensors, 'bar');

    // per ogni valore di prec calcolo la cumulata azzerandola dopo mezzanotte
    var prec = sensors[ type ];

    // la cumulata è già stata calcolata!
    let cumu = sensors[ 'PRECCUM' ];

    var valori = [];
    var cumulata = 0;
    var maxCumul = 0;
    cumu.data.forEach((valore, index) => {

        // trovo la massima delle cumulate per impostare l'asse y1
        cumulata = ( 1 * cumu.data[index].value );
        maxCumul = Math.max(maxCumul, cumulata);

        valori.push( {date : cumu.data[index].date, value: cumu.data[index].value });
        myConsoleLog('data ' + cumu.data[index].date + ' mm ' + prec.data[index].value + ' cumulata mm ' + cumu.data[index].value );

        // se sono alle 00:00 allora aggiungo un punto per spezzare la linea della cumulata
        var d = new Date( cumu.data[index].date );
        if ( ( d.getHours() == 0 ) &&  ( d.getMinutes() == 0 ) ){ 
            // se sono alla prima scansione del grafico non aggiungo nulla
            if (valori.length > 1 ) {
                // aggiungo un punto per spezzare la linea
                valori.push( {date : cumu.data[index].date, value: null });
                myConsoleLog('interruzione grafico ' + cumu.data[index].date );
            }
        }

    });

    myConsoleLog( 'prec ' + JSON.stringify(prec) );        

    let xPointStyle = 'circle';
    let xRadius = 2;
    if (isMobile() ) {
        xRadius = 0.5;
    }


    var pioggiaCumul = {
                yAxisID: 'y1',
                type: 'line',
                order: 1,
                label: 'Precipitazione cumulata',
                data: valori,
                datalabels: {
                    align: 'end', 
                    anchor: 'end',
                    offset : 2, 
                    rotation: -90, 
                    display: true,
                    formatter: function(point, context) {
                                    // label ogni ora
                                    var xLab = point.value;
                                    // per la pioggia a 0 allora nessuna label
                                    if (point.value == "0.0") {
                                        xLab = ''; 
                                    }
                                    // 2022-09-08T05:00:00
                                    // 0123456789012345678 
                                    if ( point.date.substr(14, 2) != '00' ) {
                                        xLab = '';
                                    } 
                                    // if ( isMobile() ) { xLab = ''; }
                                    return xLab;
                               }
                },
                fill: false,
                borderColor: chartsColors['RADSOL'],
                backgroundColor: chartsColors['RADSOL'],
                tension: 0,
                pointStyle: xPointStyle,
                rotation: 0,
                pointBackgroundColor: chartsColors['RADSOL'],
                pointBorderColor: chartsColors['RADSOL'],
                radius: RadiusGrafici(),
                borderWidth: WidthGrafici(),
                parsing: {
                    xAxisKey: 'date',
                    yAxisKey: 'value'
                }
            };

    // metto il primo grafico a barre
    myChart.data.datasets[0].type = 'bar';
    myChart.data.datasets[0].order = 2;
    myChart.options.scales.y.beginAtZero = true;

    // aggiungo la cumulata
    maxCumul += maxCumul*0.2;   // 20 % in più per le etichette
    // un solo decimale
    maxCumul = Math.round( maxCumul * 10 ) / 10;

    myChart.data.datasets.push(pioggiaCumul);
    myChart.options.scales.y1 = {
                type: 'linear',
                display: true,
                position: 'right',
                suggestedMax: maxCumul,
                title: {
                    display: true,
                    text: 'Cumulata (mm)'
                    }

                };           

    // la legenda la metto in ordine inverso in modo da avere prima la pioggia e poi la cumulata
    myChart.options.plugins.legend.reverse = true;

    myChart.update();

    return myChart; 


}


// costruzione del grafico sensore
//  sensors array di tutti i dati presenti nel json 
function initializeChart(type, sensors) {

    myConsoleLog('initializeChart type ' + type);

    // se ho valori da graficare
    if (! sensors[ type ].data ) { return;} 

    // in base al type realizzo il grafico opportuno
    var objGraph = null;
    if ( type.indexOf('TARIA') >= 0 ) { 
        objGraph = GraficoTARIA(type, sensors); 
    }
    if ( type.indexOf('PREC') >= 0 ) { 
        objGraph = GraficoPREC(type, sensors); 
    }
    if ( type.indexOf('VVENTO')  >= 0 ) { 
        objGraph = GraficoVVENTO(type, sensors);
    }
    if ( type.indexOf('BRILLAIST')  >= 0 ) { 
        objGraph = GraficoBRILLAIST(type, sensors);
    }
    if ( type.indexOf('NIVOM')  >= 0 ) { 
        objGraph = GraficoStandard(type, sensors, 'line');
        // questo devo solo forzarlo che parta da y = 0
        objGraph.options.scales.y.beginAtZero = true;
    }

    // tutti gli altri sensori li faccio standard
    if ( ! objGraph ) {
        objGraph = GraficoStandard(type, sensors, 'line');
    }

    // se pressione allora metto il titolo della legenda corretto
    if (type == 'PRESS') {
        objGraph.data.datasets[0].label += ' ridotta a livello del mare';
        objGraph.update();
    }

}

