// creo la tabella dei dati presenti nei grafici 
function CreaTabella(type, sensors) {
    myConsoleLog('CreaTabella');

    // gestione della seconda riga se velocità vento con la direzione
    let nSpan = 'style="text-align: center"';

    // se stazione con direzione del vento allora titolo su due righe
    let bIsDVento = false;
    let tupleDirez;
    let nomeDirez;
    Object.entries(sensors).forEach(entry => {
        const [type, sensore] = entry;

        // se type VVENTO allora anche la direzione su due colonne
        if ( type.indexOf( 'VVENTO' ) >= 0 ) {
            nomeDirez = type.replace('VVENTO', 'DVENTO');
            if ( sensors[ nomeDirez ] ) {
                bIsDVento = true;
                tupleDirez = sensors[ nomeDirez ].data;
                nSpan = 'rowspan="2" style="vertical-align: middle; text-align: center"';
            }
        }

    });

    // gestione delle colonne nell'ordine corretto della tabella dei dati finale
    let xNomiGiusti = [];
    ordineSensoriTabellaDati.forEach((nomeColonna, index) => {
        // cerco se ho il sensore nei sensori della stazione
        Object.entries(sensors).forEach(entry => {
            const [type, sensore] = entry;
            // esiste il sensore da intabellare nei sesnori della stazione?
            if ( nomeColonna == type ) {
                if ( ! xNomiGiusti[ type ] ) {
                    xNomiGiusti.push( type );
                }
            }
        });
    });

    myConsoleLog('xNomiGiusti' + JSON.stringify(xNomiGiusti) );

    // classi per centrare il contenuto
    const sC = ' class="align-middle text-center nowrap" ';

    // titoli delle colonne dei dati presenti
    let titoloDati = '<tr>' + '<th' + sC + nSpan + '>Data<br>ora solare</th>';        

    // array delle righe nella tabella
    let righe = [];
    let nRiga = 0;
    let iTab;       // variabile per ciclare sui dati dei sensori
    let bAssente = false;       // flag per mettere >> solo se ci sono dati assenti in tabella

    // ciclo tutti i sensori presenti  nell'ordine delle colonne da scrivere
    xNomiGiusti.forEach((nomeColonna, index) => {

        const sensore = sensors[nomeColonna];
        const type = nomeColonna; 


        // correggo i nomi del sensore per l'intestazione delle colonne
        let nomeSensore = sensore.label.replace(' a ', '<br>a '); 
        nomeSensore = nomeSensore.replace('Precipitazione cumulata', 'Precipitazione<br>cumulata dalle<br>ore 24'); 
        nomeSensore = nomeSensore.replace('Radiazione ', 'Radiazione<br>');
        nomeSensore = nomeSensore.replace('Pressione', 'Pressione atmosferica<br>ridotta a livello<br>del mare');          

        // intestazioni delle colonne: nome del sensore e unità  di misura
        if ( (type.indexOf('VVENTO') >= 0 ) && (bIsDVento) ) { 
            titoloDati += '<th' + sC + ' colspan="2" style="text-align: center">' + nomeSensore + '</th>';
        } else if (type.indexOf('DVENTO') >= 0 ) {
            // non devo mettere la colonna della DVENTO in quanto viene messa se esiste
        } else {
            titoloDati += '<th' + sC + nSpan + '>' + nomeSensore + ' (' + sensore.unitmeas + ')</th>';
        }  

        // compongo le righe e colonne della tabella dei dati
        sensore.data.forEach((tuplaDatiSensore, index) => {
            var dataora = tuplaDatiSensore.date;     
            // 2022-09-08T05:00:00
            // 0123456789012345678 
            dataora = dataora.substr(8, 2) + '/' + dataora.substr(5, 2) + '/' + dataora.substr(0, 4) + ' ' + 
                        dataora.substr(11, 2) + ':' + dataora.substr(14, 2);
            // 08/09/2022 05:00              

            var valore = tuplaDatiSensore.value;

            // cerco la riga nella righe 
            let bCarica = true;
            for (iTab in righe) {       // uso il for per avere il break
                if ( righe[iTab].dataora == dataora ) {
                    bCarica = false;
                    nRiga = iTab;
                    break;
                } 
            }                
            if ( bCarica ) { 

                // aggiungo la riga nella tabella da pubblicare
                nRiga = righe.push( { dataora: dataora } );
                nRiga -= 1;  // zero based
            }                

            // valore da intabellare 
            if ( ! isNumeric( valore ) ) {
                bAssente = true;
                valore = '>>';
            }
            righe[nRiga][type] = valore; 

            // se sensore VVento ho anche la direzione da mettere prendendola dal sensore corretto
            if (type.indexOf('VVENTO') >= 0 ) { 
                righe[ nRiga ][ nomeDirez ] = tupleDirez[ index ].value;
            }

        });     // sensore.data.forEach((valore, index) => { 

    });        

    titoloDati += '</tr>';
    // seconda riga se dvento
    if ( bIsDVento ) {
        titoloDati += 
            '<tr>' + 
            '<th' + sC + '>Velocità <br>(m/s)</th>' + 
            '<th' + sC + '>Provenienza<br>(gradi)</th>' + 
            '</tr>';
    }         

    // ordino per dataora decrescente
    //    righe.sort( (a,b) => (a.dataora > b.dataora) ? -1 : ((b.dataora > a.dataora) ? 1 : 0));

    righe.sort( function(a,b) { 
        const aIst = new Date().ConvDataOra( a.dataora );
        const bIst = new Date().ConvDataOra( b.dataora );
        let ret = 0;
        if (aIst.Formato('YYYYMMDDHHmm') > bIst.Formato('YYYYMMDDHHmm')) { 
            ret = -1; 
        } else {
            if (bIst.Formato('YYYYMMDDHHmm') > aIst.Formato('YYYYMMDDHHmm')) {
                ret = 1;
            }
        }
        return ret;
        }
    );

    myConsoleLog('righe' + JSON.stringify(righe) );

    let righeDati = '';
    for (iTab in righe) {
        let tupla = righe[iTab];
        righeDati += '<tr>';

        // dataora della riga
        righeDati += '<td class="text-right nowrap">' + tupla.dataora + '</td>';

        // per tutte le colonne della riga
        xNomiGiusti.forEach((nomeColonna, index) => {
            let vv = '';
            if ( Object.hasOwn(tupla, nomeColonna) ) {
                vv = tupla[nomeColonna];
            }
            righeDati += '<td class="text-right nowrap">' + vv + '</td>';
        });
        righeDati += '</tr>';
    }  

    var tabDati = '';
    tabDati +=   '<div class="modal-body" style="height: 400px;overflow-y: scroll; padding: 0px!important">';
    tabDati +=     '<table id="tabellaDati" class="table table-sm table-striped table-bordered table-hover table-condensed">';        
    tabDati +=     '<thead style="position: sticky;  top: 0;">' + titoloDati + '</thead>';
    tabDati +=     '<tbody>' + righeDati + '</tbody>';
    tabDati +=     '</table><br>';

    tabDati +=   '</div>';

    // div dove mettere la tabella        
    const divTabella = document.getElementById('tabcontent-' + type);
    divTabella.innerHTML = tabDati;
    document.getElementById('meteoTabPanelContent').append(divTabella);

    // note e link fuori dal riquadro scrollabile, prima del testo "Dati aggiornati il..."
    let infoDati = '';
    if ( bAssente ) { infoDati += 'Con >> dato assente.<br>'; }  
    if ( bIsDVento) { infoDati += 'La provenienza del vento indica con 0=Nord, 90=Est, 180=Sud, 270=Ovest.<br>'; }  
    infoDati += '<a href="' + linkJsonDati + '" target="_blank" type="text/json">Dati della stazione in formato JSON</a>';
    infoDati += '<br><a href="#" id="lnkSalvaTabellaDati">Dati della stazione in formato CSV</a>';

    const divInfoDati = document.createElement('div');
    divInfoDati.setAttribute('id', 'infoDatiTabella');
    divInfoDati.setAttribute('class', 'modal-body');
    divInfoDati.innerHTML = infoDati;
    document.getElementById('meteoTabPanelContent').append(divInfoDati);

    // download CSV della tabella visualizzata (separatore ';' per Excel)
    document.getElementById('lnkSalvaTabellaDati').onclick = function (ev) {
        ev.preventDefault();
        const tabella = document.getElementById('tabellaDati');
        if (!tabella) { return; }

        const separatore = ',';
        const escapeCsv = function (valore) {
            const testo = (valore || '').replace(/\s+/g, ' ').trim();
            if (testo.indexOf('"') >= 0 || testo.indexOf(separatore) >= 0 || testo.indexOf('\n') >= 0) {
                return '"' + testo.replaceAll('"', '""') + '"';
            }
            return testo;
        };

        const righe = tabella.querySelectorAll('tr');
        const righeCsv = [];
        const occupateFinoA = [];
        let maxColonne = 0;

        righe.forEach((riga, idxRiga) => {
            const celleCsv = [];
            let idxColonna = 0;

            // salta le colonne coperte da rowspan delle righe precedenti
            while (occupateFinoA[idxColonna] > idxRiga) {
                celleCsv[idxColonna] = '';
                idxColonna += 1;
            }

            riga.querySelectorAll('th,td').forEach((cella) => {
                while (occupateFinoA[idxColonna] > idxRiga) {
                    celleCsv[idxColonna] = '';
                    idxColonna += 1;
                }

                const colspan = parseInt(cella.getAttribute('colspan') || '1', 10);
                const rowspan = parseInt(cella.getAttribute('rowspan') || '1', 10);
                const valore = escapeCsv(cella.innerText);

                for (let i = 0; i < colspan; i++) {
                    celleCsv[idxColonna + i] = valore;
                    if (rowspan > 1) {
                        occupateFinoA[idxColonna + i] = idxRiga + rowspan;
                    }
                }

                idxColonna += colspan;
            });

            maxColonne = Math.max(maxColonne, celleCsv.length);
            righeCsv.push(celleCsv);
        });

        const righeCsvTesto = righeCsv.map((celleCsv) => {
            for (let i = 0; i < maxColonne; i++) {
                if (celleCsv[i] === undefined) {
                    celleCsv[i] = '';
                }
            }
            return celleCsv.join(separatore);
        });

        const csv = '\uFEFF' + righeCsvTesto.join('\r\n');
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'datiInDiretta_' + nomeStazione.replaceAll(' ', '_') + '.csv';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

}


