        // parto dal primo pulsante presente
        let primoPulsante = Object.values(pulsanti)[0].targa;
        // se ho il focus allora mappa sul sensore desiderato (se c'è)
        if (focus.length > 0) {
            primoPulsante = focus;
        }
        document.getElementById( 'btn' + primoPulsante ).click();
    } else {

        // imposto il font di default dei grafici il font della tabella
        if (isMobile() ) {
            ARPAVAPI.Chart.defaults.font.size = 7;
            AddStyle(7);
        } else {
            ARPAVAPI.Chart.defaults.font.size = 16;
            AddStyle(15);
        }
        GraficiStazione(codseqst, focus, typeReturn);
    }


}

generateHTML();
